import{_ as e,c as t,o as a,ae as l}from"./chunks/framework.BrQRMotl.js";const u=JSON.parse('{"title":"スムーズ移動コマンド (Smooth Move)","description":"","frontmatter":{},"headers":[],"relativePath":"ja/manual/smooth_move.md","filePath":"ja/manual/smooth_move.md"}'),i={name:"ja/manual/smooth_move.md"};function s(c,o,n,d,r,h){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="スムーズ移動コマンド-smooth-move" tabindex="-1">スムーズ移動コマンド (Smooth Move) <a class="header-anchor" href="#スムーズ移動コマンド-smooth-move" aria-label="Permalink to &quot;スムーズ移動コマンド (Smooth Move)&quot;">​</a></h1><p><code>/smoothmove</code> は、管理者がプレイヤーやエンティティを指定した方向に滑らかな速度で移動させることを可能にする強力なユーティリティコマンドです。</p><h2 id="コマンド構文" tabindex="-1">コマンド構文 <a class="header-anchor" href="#コマンド構文" aria-label="Permalink to &quot;コマンド構文&quot;">​</a></h2><h3 id="_1-移動開始" tabindex="-1">1. 移動開始 <a class="header-anchor" href="#_1-移動開始" aria-label="Permalink to &quot;1. 移動開始&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove &lt;target&gt; &lt;direction&gt; &lt;speed&gt; [duration]</span></span></code></pre></div><ul><li><strong>target</strong>: 移動させるエンティティセレクタ（例: <code>@s</code>, <code>@p</code>, <code>@e[type=zombie]</code>）。</li><li><strong>direction</strong>: <ul><li><code>north</code>, <code>south</code>, <code>east</code>, <code>west</code>: 東西南北。</li><li><code>x</code>, <code>-x</code>, <code>y</code>, <code>-y</code>, <code>z</code>, <code>-z</code>: 座標軸方向。</li><li><code>forward</code>: プレイヤーが現在水平方向に向いている向き。</li><li><code>look</code>: プレイヤーの視線が向いている正確な方向（垂直成分を含む）。</li></ul></li><li><strong>speed</strong>: 1 Tick あたりの移動距離（1 は 20ブロック/秒に相当、TPS=20）。</li><li><strong>duration</strong> (オプション): 移動が継続する Tick 数。省略した場合、その速度で移動し続けます。</li></ul><h3 id="_2-移動停止" tabindex="-1">2. 移動停止 <a class="header-anchor" href="#_2-移動停止" aria-label="Permalink to &quot;2. 移動停止&quot;">​</a></h3><div class="language-mcfunction vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mcfunction</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/smoothmove stop &lt;target&gt;</span></span></code></pre></div><ul><li>指定したエンティティのスムーズ移動状態を即座に強制停止します。</li></ul><h2 id="コア機能" tabindex="-1">コア機能 <a class="header-anchor" href="#コア機能" aria-label="Permalink to &quot;コア機能&quot;">​</a></h2><ol><li><strong>壁抜け (NoClip)</strong>: <ul><li>スムーズ移動中、エンティティは <code>noClip</code> 状態（スペクテイターモードに類似）になり、ブロックを通り抜けることができ、挟まったり衝突したりしません。</li></ul></li><li><strong>サーバー制御</strong>: <ul><li>移動軌道はサーバーによって強制的に同期されるため、ネットワーク遅延や衝突判定によるクライアント側のカクつき（ラバーバンド現象）が排除されます。</li></ul></li><li><strong>安全保護</strong>: <ul><li>移動中、エンティティの落下ダメージは 0 にリセットされ、長距離移動後の着地による死亡を防ぎます。</li><li>移動終了または停止後、エンティティは通常の衝突判定に戻ります。</li></ul></li></ol>',11)])])}const p=e(i,[["render",s]]);export{u as __pageData,p as default};
